const CATEGORIES=['演出宣传','技艺展示','幕后记录','艺术科普'];
const WEEKDAYS=['周一','周二','周三','周四','周五','周六','周日'];
const SUPPLIERS={
  'OpenAI 官方':{url:'https://api.openai.com/v1',model:'gpt-4o-mini'},
  'DeepSeek':{url:'https://api.deepseek.com/v1',model:'deepseek-chat'},
  '通义千问':{url:'https://dashscope.aliyuncs.com/compatible-mode/v1',model:'qwen-plus'},
  '智谱':{url:'https://open.bigmodel.cn/api/paas/v4',model:'glm-4-flash'},
  'Moonshot':{url:'https://api.moonshot.cn/v1',model:'moonshot-v1-8k'},
  '自定义':{url:'',model:''}
};
const pages={overview:'运营总览',records:'内容记录',analysis:'效果分析',suggestions:'排期建议',calendar:'排期日历',settings:'模型接口设置'};
const state={page:'overview',teamId:Number(localStorage.getItem('artsTeamId')||1),user:null,calendarMode:'month',monthOffset:0,records:[],recordsSearch:'',recordsStatus:'',recordsPlatform:'',recordsCategory:'',recordsSort:'published_at',recordsOrder:'desc',recordsPage:1,recordsPageSize:10,selectedRecords:[],overview:null,settings:null,recommendation:null,draft:null,calendar:[],hypotheses:[]};
const qs=(s,root=document)=>root.querySelector(s),qsa=(s,root=document)=>[...root.querySelectorAll(s)];
const pad=n=>String(n).padStart(2,'0');
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('zh-CN');
function toast(msg){const el=qs('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
function apiHeaders(extra={}){const token=sessionStorage.getItem('artsSessionToken');return {'X-Team-Id':String(state.teamId),...(token?{'Authorization':`Bearer ${token}`}:{ }),...extra}}
async function api(url,options={}){const headers=apiHeaders(options.headers||{});if(!(options.body instanceof FormData)&&options.body)headers['Content-Type']='application/json';const response=await fetch(url,{...options,headers});if(!response.ok){let message=`请求失败 (${response.status})`;try{const body=await response.json();message=typeof body.detail==='string'?body.detail:body.detail?.message||JSON.stringify(body.detail||body)}catch{}throw new Error(message)}const type=response.headers.get('content-type')||'';return type.includes('application/json')?response.json():response}
async function downloadApi(path){try{const response=await fetch(path,{headers:apiHeaders()});if(!response.ok){let message=`导出失败（${response.status}）`;try{const body=await response.json();message=body.detail||message}catch{}throw new Error(message)}const disposition=response.headers.get('content-disposition')||'';const encoded=disposition.match(/filename\*=UTF-8''([^;]+)/i);const plain=disposition.match(/filename=\"?([^;\"]+)/i);const filename=encoded?decodeURIComponent(encoded[1]):plain?plain[1]:'export.bin';const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){toast(e.message)}}
function heading(kicker,title,desc,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function emptyState(title='从一条记录开始，留住团队的好经验'){return `<div class="empty-state"><div class="empty-icon">❋</div><h3>${title}</h3><p>录入团队自己的发布记录后，这里会呈现真实的传播表现和复盘线索。</p><button class="btn-primary" data-goto="records">＋ 录入内容</button></div>`}
function statCard(label,value,foot,icon='◫'){return `<div class="stat-card"><div class="stat-label"><span class="stat-icon">${icon}</span>${label}</div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></div>`}
function sampleLabel(n,min){return n<min?'样本不足':n<=min*2?'样本较少，仅供参考':`${n} 条记录`}
function tag(text,cls='type-tag'){return `<span class="${cls}">${escapeHtml(text||'—')}</span>`}
function scoreText(value){return value==null?'样本不足':`${Math.round(value)}分`}
function refresh(){return api('/api/contents').then(d=>state.records=d.items).then(()=>api('/api/stats/overview')).then(d=>state.overview=d).then(()=>api('/api/settings')).then(d=>state.settings=d)}
async function go(page){state.page=page;qsa('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));qs('#crumb').textContent=pages[page]||page;qs('#sidebar').classList.remove('open');await render()}
async function render(){const root=qs('#pageRoot');root.innerHTML='<section class="panel loading-state"><span class="loading-spinner"></span>正在加载…</section>';try{await refresh();const fn={overview:overviewPage,records:recordsPage,analysis:analysisPage,suggestions:suggestionsPage,calendar:calendarPage,settings:settingsPage}[state.page]||overviewPage;root.innerHTML=await fn();wirePage()}catch(e){root.innerHTML=`<div class="empty-state error-state"><div class="empty-icon">!</div><h3>页面暂时无法加载</h3><p>${escapeHtml(e.message)}<br>请检查服务状态后重试。</p><button class="btn-primary" data-action="retry">重新加载</button></div>`;wirePage()}}
function trendSvg(records){if(!records.length)return `<div class="chart-empty">还没有可显示的趋势数据</div>`;const arr=[...records].sort((a,b)=>a.published_at.localeCompare(b.published_at));const max=Math.max(1,...arr.map(x=>x.views));const top=Math.max(1,...arr.map(x=>x.total_interactions));const line=(field,scale)=>arr.map((x,i)=>`${30+i*250/Math.max(arr.length-1,1)},${145-(x[field]||0)/scale*108}`).join(' ');return `<div class="trend-chart"><svg viewBox="0 0 300 175" preserveAspectRatio="none"><defs><linearGradient id="areaFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#566477" stop-opacity=".18"/><stop offset="1" stop-color="#566477" stop-opacity="0"/></linearGradient></defs>${[30,65,100,135].map(y=>`<line x1="25" x2="292" y1="${y}" y2="${y}" class="chart-gridline"/>`).join('')}<polyline points="${line('views',max)}" class="chart-line"/><polyline points="${line('total_interactions',top)}" class="chart-line red"/>${arr.map((x,i)=>`<circle cx="${30+i*250/Math.max(arr.length-1,1)}" cy="${145-x.views/max*108}" r="3" class="chart-point"><title>${escapeHtml(x.title)} · ${fmt(x.views)} 播放</title></circle>`).join('')}<text x="27" y="166" class="chart-axis">${arr[0].published_at.slice(5,10)}</text><text x="252" y="166" class="chart-axis">${arr.at(-1).published_at.slice(5,10)}</text></svg></div>`}
async function safeApi(path,fallback,label){try{return await api(path)}catch(e){console.error(`${label}加载失败`,e);return fallback}}
async function platformPerformance(minSample){try{const result=await api('/api/stats/platform');const items=Array.isArray(result.items)?result.items:[];if(!items.length)return '<div class="chart-empty">暂无平台记录，录入内容后会显示平台表现。</div>';const max=Math.max(1,...items.map(p=>Number(p.total_views)||0));return `<div class="platform-list">${items.map(p=>`<div class="platform-row"><span class="platform-name">${escapeHtml(p.name)}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.min(100,(Number(p.total_views)||0)/max*100)}%"></div></div><span class="platform-count">${fmt(p.total_views)} 播放</span></div>`).join('')}</div><p class="form-help">总量为录入数据；样本门槛 ${minSample} 条以下不用于推断均值。</p>`}catch(e){console.error('平台表现加载失败',e);return `<div class="chart-empty error-text">平台表现暂时无法加载：${escapeHtml(e.message||'接口异常')}</div>`}}
async function overviewPage(){const o=state.overview,r=state.records,cfg=state.settings,min=cfg.min_sample;const avg=o.avg_completion<0?0:o.avg_completion;const platformHtml=await platformPerformance(min);const [adoption,funnel,diagnostics]=await Promise.all([safeApi('/api/stats/adoption',{adopted:{avg_completion:null,sample_count:0},not_adopted:{avg_completion:null,sample_count:0},completion_difference:null},'采纳统计'),safeApi('/api/stats/funnel',{views:0,profile_visits:0,follows:0,attendance:0,tickets:0,sample_count:0},'转化漏斗'),safeApi('/api/stats/diagnostics',{items:[]},'运营提醒')]);const completions=avg>=0&&o.sample_count>=min?`${avg}%`:'<span class="small-value">样本不足</span>';return `${heading('TEAM REVIEW · 01','运营总览','算出艺术怎样才能被看见',`<button class="btn-secondary" data-action="export-report">导出 PDF 复盘</button><button class="btn-primary" data-goto="records">＋ 录入内容</button>`)}
<div class="grid stats-grid">${statCard('已发布内容',`${o.total_posts}<em> 条</em>`,`${o.total_assets} 条内容资产 · ${o.unpublished_count} 条未发布`,'▤')}${statCard('总播放量',fmt(o.total_views),`${o.platform_count} 个平台 · 统计口径：后台记录`,'◉')}${statCard('总互动量',fmt(o.total_interactions),'点赞、评论、收藏与转发','♡')}${statCard('平均看完比例',completions,`${o.sample_count} 条记录 · ${sampleLabel(o.sample_count,min)}`,'◷')}</div>
<div class="grid overview-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">传播表现趋势</h2><div class="panel-subtitle">每条内容发布后的播放与互动记录</div></div><div class="chart-legend"><span><i class="legend-dot"></i>播放量</span><span><i class="legend-dot red"></i>互动量</span></div></div>${trendSvg(r.filter(x=>x.lifecycle==='已发布'))}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">平台表现</h2><div class="panel-subtitle">平台口径可能不同，跨平台对比仅作参考</div></div></div>${platformHtml}<div class="completeness"><div class="ring"><span>${Math.min(100,Math.round(o.total_posts/Math.max(min,10)*100))}%</span></div><div class="complete-copy"><b>数据完整度 ${o.sample_count<min?'仍在积累':'基础可用'}</b><small>${o.sample_count<min?`当前数据量还不足够支撑准确分析，至少需要 ${min} 条同类记录。`:'分析仅基于团队自身历史数据。'}</small></div></div></section></div>
<div class="grid content-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">优质内容</h2><div class="panel-subtitle">综合分 = 看完比例 × 完播权重 + 互动比例 × 互动权重</div></div><button class="btn-secondary" data-goto="analysis">查看分析</button></div><div class="rank-list">${o.top_contents.slice(0,3).map((x,i)=>`<div class="rank-item"><span class="rank-mark">${String(i+1).padStart(2,'0')}</span><div class="rank-copy"><b>${escapeHtml(x.title)}</b><small>${tag(x.category)} · ${escapeHtml(x.platform)}</small></div><span class="score">${x.score}分</span></div>`).join('')||'<div class="hint">暂时没有内容</div>'}</div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">采纳建议后的表现</h2><div class="panel-subtitle">对比采纳与未采纳记录，样本少时谨慎解读</div></div></div><div class="adoption-grid"><div><small>采纳建议</small><b>${adoption.adopted.avg_completion==null?'—':adoption.adopted.avg_completion+'%'}</b><span>${adoption.adopted.sample_count} 条</span></div><div><small>未采纳</small><b>${adoption.not_adopted.avg_completion==null?'—':adoption.not_adopted.avg_completion+'%'}</b><span>${adoption.not_adopted.sample_count} 条</span></div></div><p class="form-help">${adoption.completion_difference==null?'完成采纳排期并回填实际数据后，会显示两组差异。':`采纳组平均看完比例 ${adoption.completion_difference>=0?'高':'低'} ${Math.abs(adoption.completion_difference)} 个百分点。样本量：${adoption.adopted.sample_count} vs ${adoption.not_adopted.sample_count}。`}</p><div class="funnel-row">播放 ${fmt(funnel.views)} → 主页访问 ${fmt(funnel.profile_visits)} → 关注 ${fmt(funnel.follows)} → 到场 ${fmt(funnel.attendance)} / 购票 ${fmt(funnel.tickets)}</div></section></div>
${diagnostics.items.length?`<section class="panel" style="margin-top:15px"><h2 class="panel-title">运营节奏提醒</h2>${diagnostics.items.slice(0,3).map(x=>`<div class="insight"><span class="insight-symbol">${x.level==='good'?'✦':'!'}</span><div><p>${escapeHtml(x.message)}</p></div></div>`).join('')}</section>`:''}`}
async function recordsPage(){
 const all=state.records,editor=['owner','editor'].includes(state.user?.role),filtered=filteredRecords(all),pageCount=Math.max(1,Math.ceil(filtered.length/state.recordsPageSize));
 state.recordsPage=Math.min(state.recordsPage,pageCount);const start=(state.recordsPage-1)*state.recordsPageSize,rows=filtered.slice(start,start+state.recordsPageSize),selected=new Set(state.selectedRecords),visibleSelected=rows.filter(x=>selected.has(x.id)).length;
 const actions=`<button class="btn-secondary" data-action="template">下载 CSV 模板</button><button class="btn-secondary" data-action="export-content-csv">导出内容 CSV</button>${editor?'<button class="btn-primary" data-action="open-add">＋ 手动录入</button>':''}`;
 const platforms=[...new Set(all.map(x=>x.platform).filter(Boolean))].sort(),categories=[...new Set(all.map(x=>x.category).filter(Boolean))].sort();
 const list=rows.length?`<div class="table-wrap"><table class="data-table records-table"><thead><tr>${editor?`<th><input type="checkbox" id="selectVisible" ${visibleSelected===rows.length&&rows.length?'checked':''} aria-label="选择本页"></th>`:''}<th>内容资产</th><th>发布时间</th><th>内容类型</th><th>状态标签</th><th>播放量</th><th>互动量</th><th>看完比例</th><th>负责人</th>${editor?'<th>操作</th>':''}</tr></thead><tbody>${rows.map(x=>`<tr>${editor?`<td><input type="checkbox" data-record-select="${x.id}" ${selected.has(x.id)?'checked':''} aria-label="选择 ${escapeHtml(x.title)}"></td>`:''}<td class="content-title-cell"><b>${escapeHtml(x.title)}</b><small>${tag(x.platform,'platform-tag')} ${x.tags?.map(t=>tag(t)).join(' ')||''}</small></td><td>${escapeHtml(x.published_at.slice(0,16).replace('T',' '))}</td><td>${tag(x.category)}</td><td>${editor?`<select class="inline-select status-select" data-lifecycle="${x.id}"><option ${x.lifecycle==='已发布'?'selected':''}>已发布</option><option ${x.lifecycle==='未发布'?'selected':''}>未发布</option></select>`:`<span class="status-pill ${x.lifecycle==='已发布'?'published':'unpublished'}">${escapeHtml(x.lifecycle)}</span>`}</td><td>${fmt(x.views)}</td><td>${fmt(x.total_interactions)}</td><td>${x.completion}%</td><td>${escapeHtml(x.owner||'未分配')}</td>${editor?`<td><button class="btn-secondary" data-action="edit-record" data-id="${x.id}">编辑</button> <button class="btn-secondary" data-action="delete-record" data-id="${x.id}">删除</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:all.length?'<div class="chart-empty">没有符合当前筛选条件的记录，请调整搜索或筛选条件。</div>':editor?emptyState('还没有内容资产'):'<div class="chart-empty">暂无内容记录，请联系团队录入者添加资产。</div>';
 return `${heading('YOUR RECORDS · 02','内容记录','按标题、平台、状态和发布时间管理团队内容资产',actions)}
 <section class="panel records-filters"><div class="filter-grid"><label class="form-field"><span>搜索标题 / 标签 / 负责人</span><input id="recordsSearch" value="${escapeHtml(state.recordsSearch)}" placeholder="输入关键词"/></label><label class="form-field"><span>平台</span><select id="recordsPlatform"><option value="">全部平台</option>${platforms.map(x=>`<option ${x===state.recordsPlatform?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select></label><label class="form-field"><span>内容类型</span><select id="recordsCategory"><option value="">全部类型</option>${categories.map(x=>`<option ${x===state.recordsCategory?'selected':''}>${escapeHtml(x)}</option>`).join('')}</select></label><label class="form-field"><span>状态标签</span><select id="recordsStatus"><option value="">全部状态</option><option ${state.recordsStatus==='已发布'?'selected':''}>已发布</option><option ${state.recordsStatus==='未发布'?'selected':''}>未发布</option></select></label><label class="form-field"><span>排序</span><select id="recordsSort"><option value="published_at" ${state.recordsSort==='published_at'?'selected':''}>发布时间</option><option value="views" ${state.recordsSort==='views'?'selected':''}>播放量</option><option value="completion" ${state.recordsSort==='completion'?'selected':''}>看完比例</option><option value="title" ${state.recordsSort==='title'?'selected':''}>标题</option></select></label><label class="form-field"><span>顺序</span><select id="recordsOrder"><option value="desc" ${state.recordsOrder==='desc'?'selected':''}>降序</option><option value="asc" ${state.recordsOrder==='asc'?'selected':''}>升序</option></select></label></div><div class="filter-summary">共 ${all.length} 条记录 · 当前筛选 ${filtered.length} 条</div></section>
 ${editor?`<section class="panel import-panel"><div class="panel-head"><div><h2 class="panel-title">CSV 批量导入</h2><div class="panel-subtitle">必填：平台、发布时间、标题、播放量、点赞量；未填写状态时默认“已发布”</div></div><input id="csvFile" type="file" accept=".csv,text/csv" aria-label="选择 CSV 文件"/></div><details class="csv-guide"><summary>查看字段说明</summary><p><b>必填</b>：平台、发布时间（YYYY-MM-DD HH:mm）、标题、播放量、点赞量。</p><p><b>选填</b>：内容类型、时长、评论量、收藏量、转发量、看完比例（0–100）、状态标签（已发布/未发布，默认已发布）、标签（竖线分隔）、素材说明、责任人、备注、主页访问、新增关注、到场人数、售票数、评论摘录。</p></details></section>`:''}
 <section class="panel records-list"><div class="panel-head"><div><h2 class="panel-title">团队内容资产</h2><div class="panel-subtitle">${all.length} 条 · 状态仅有“已发布”和“未发布”</div></div></div>${editor&&selected.size?`<div class="bulk-toolbar"><b>已选 ${selected.size} 条</b><button class="btn-secondary" data-action="bulk-publish">设为已发布</button><button class="btn-secondary" data-action="bulk-unpublish">设为未发布</button><button class="btn-secondary danger-action" data-action="bulk-delete">批量删除</button></div>`:''}${list}<div class="pagination"><span>第 ${state.recordsPage} / ${pageCount} 页</span><label>每页<select id="recordsPageSize"><option value="10" ${state.recordsPageSize===10?'selected':''}>10</option><option value="20" ${state.recordsPageSize===20?'selected':''}>20</option><option value="50" ${state.recordsPageSize===50?'selected':''}>50</option></select></label><div><button class="btn-secondary" data-action="records-prev" ${state.recordsPage<=1?'disabled':''}>上一页</button><button class="btn-secondary" data-action="records-next" ${state.recordsPage>=pageCount?'disabled':''}>下一页</button></div></div></section>
 <section class="panel" style="margin-top:15px"><div class="panel-head"><h2 class="panel-title">A/B 假设与结论</h2></div><form id="hypothesisForm" class="inline-form"><input name="statement" required placeholder="例如：开头先展示制作过程会提高看完比例"/><button class="btn-primary">记录假设</button></form><div id="hypothesisList" class="hypothesis-list">加载中…</div></section>`
}
function filteredRecords(records){let items=[...records];const q=state.recordsSearch.trim().toLocaleLowerCase();if(q)items=items.filter(x=>[x.title,x.platform,x.owner,x.notes,...(x.tags||[])].join(' ').toLocaleLowerCase().includes(q));if(state.recordsStatus)items=items.filter(x=>x.lifecycle===state.recordsStatus);if(state.recordsPlatform)items=items.filter(x=>x.platform===state.recordsPlatform);if(state.recordsCategory)items=items.filter(x=>x.category===state.recordsCategory);const key=state.recordsSort,dir=state.recordsOrder==='asc'?1:-1;items.sort((a,b)=>{const av=a[key]??'',bv=b[key]??'';return (typeof av==='number'?av-bv:String(av).localeCompare(String(bv),'zh-CN'))*dir});return items}

async function analysisPage(){const [cat,heat,bench,adoption]=await Promise.all([api('/api/stats/category'),api('/api/stats/heatmap'),api('/api/benchmark'),api('/api/stats/adoption')]);const min=cat.min_sample;const cells=heat.items;const has=state.records.length>0;return `${heading('CONTENT REVIEW · 03','效果分析','多条件效果对比和团队自身基准，不代表行业平均',`<button class="btn-secondary" data-action="export-anonymized">导出脱敏 CSV</button>`)}${!has?emptyState():''}<div class="grid analysis-top">${statCard('纳入复盘',`${state.records.length}<em> 条</em>`,`当前样本门槛 ${min} 条`,'▤')}${statCard('平均看完比例',state.records.length>=min?`${state.overview.avg_completion}%`:'样本不足',sampleLabel(state.records.length,min),'◷')}${statCard('采纳组看完比例',adoption.adopted.avg_completion==null?'—':`${adoption.adopted.avg_completion}%`,`${adoption.adopted.sample_count} 条采纳记录`,'✳')}</div><div class="grid overview-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">内容类型表现</h2><div class="panel-subtitle">样本低于 ${min} 条时不展示均值；当前数据仅反映团队自身</div></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>内容类型</th><th>记录数</th><th>平均播放</th><th>平均看完</th><th>互动比例</th><th>自身基准</th></tr></thead><tbody>${CATEGORIES.map(name=>{const x=cat.items.find(i=>i.name===name),b=bench.find(i=>i.category===name);return `<tr><td>${name}</td><td>${x?.sample_count||0}</td><td>${x?.views==null?'样本不足':fmt(Math.round(x.views))}</td><td>${x?.completion==null?'样本不足':x.completion+'%'}</td><td>${x?.interaction_rate==null?'样本不足':x.interaction_rate+'%'}</td><td>${b?.completion_median==null?'样本不足':b.completion_median+'% · '+(b.source_label||'自身历史')} <button class="btn-secondary" data-action="edit-benchmark" data-category="${name}" data-value="${b?.completion_median??''}" data-interaction="${b?.interaction_median??''}">调整</button></td></tr>`}).join('')}</tbody></table></div><div class="insight"><span class="insight-symbol">✦</span><div><b>综合表现分的计算方式</b><p>看完比例 × 完播权重 + 互动比例 × 互动权重。当前权重 ${cat.weights.completion} / ${cat.weights.interaction}，可在模型接口设置页调整。</p></div></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">星期与时段表现</h2><div class="panel-subtitle">低于样本门槛时留空，避免把偶然结果当规律</div></div></div><div class="heatmap"><div class="heat-head">星期 / 时段</div>${['上午','午间','下午','晚间','夜间'].map(x=>`<div class="heat-head">${x}</div>`).join('')}${WEEKDAYS.map((d,di)=>`<div class="heat-head">${d}</div>${['上午','午间','下午','晚间','夜间'].map(slot=>{const x=cells.find(i=>i.weekday===di&&i.time_slot===slot);return `<div class="heat-cell ${x?.completion!=null?'heat-'+Math.min(5,Math.max(1,Math.round(x.completion/20))):'heat-1'}" title="${x?.sample_count||0} 条样本">${x?.completion==null?'样本不足':x.completion+'%'}</div>`}).join('')}`).join('')}</div></section></div><div class="grid overview-grid" style="margin-top:15px"><section class="panel"><h2 class="panel-title">转化漏斗</h2><div class="funnel-view">${await funnelMarkup()}</div></section><section class="panel"><h2 class="panel-title">评论倾向与关键词</h2>${await sentimentMarkup()}</section></div><section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2 class="panel-title">用自然语言问团队数据</h2><div class="panel-subtitle">模型未配置或失败时，自动用规则统计回答</div></div></div><form id="insightForm" class="inline-form"><input name="question" required placeholder="例如：什么类型的内容看完比例较高？"/><button class="btn-primary">生成洞察</button></form><div id="insightResult"></div></section><section class="panel" style="margin-top:15px"><div class="panel-head"><h2 class="panel-title">换届交接包</h2><button class="btn-primary" data-action="handover">导出 Markdown</button></div><p class="form-help">打包高优内容、复盘结论、排期经验与下一步待办，方便团队交接。</p></section>`}
async function funnelMarkup(){const f=await api('/api/stats/funnel');const steps=[['播放',f.views],['进主页',f.profile_visits],['关注',f.follows],['到场',f.attendance],['购票',f.tickets]],max=Math.max(1,f.views);return `<div class="funnel-bars">${steps.map(([label,n])=>`<div><span>${label}</span><div class="bar-track"><div class="bar-fill" style="width:${n?Math.max(2,n/max*100):0}%"></div></div><b>${fmt(n)}</b></div>`).join('')}</div><small class="disclaimer">按团队主动录入的转化数据统计；${f.sample_count} 条内容。</small>`}
async function sentimentMarkup(){const words={positive:new Set(['清晰','喜欢','精彩','漂亮','好看','有趣','打动','细致','期待','优秀','棒']),negative:new Set(['太长','看不懂','模糊','太贵','不清楚','无聊','赶','难','一般','不喜欢'])};const text=state.records.map(x=>x.comment_text||'').join(' ');const tokens=text.match(/[\u4e00-\u9fa5]{2,6}/g)||[];const counts=new Map();tokens.forEach(t=>counts.set(t,(counts.get(t)||0)+1));const top=[...counts].sort((a,b)=>b[1]-a[1]).slice(0,8);const pos=[...words.positive].filter(w=>text.includes(w)).length,neg=[...words.negative].filter(w=>text.includes(w)).length;return `<p class="form-help">当前录入评论文本 ${text?1:0} 组；关键词使用本地词表粗略整理，不读取平台评论。</p><div class="sentiment"><span>正向词 ${pos}</span><span>需关注词 ${neg}</span></div><div class="keyword-list">${top.map(([w,n])=>tag(`${w} × ${n}`,'type-tag')).join(' ')||'暂无评论文本'}</div><small class="disclaimer">只分析团队主动录入的评论摘要，不采集观众个人信息。</small>`}
async function suggestionsPage(){const history=await api('/api/recommendations');return `${heading('NEXT WEEK · 04','排期建议','根据团队自有数据生成建议；每条结论均显示参考样本量',`<button class="btn-secondary" data-action="export-report">导出 PDF 报告</button><button class="btn-primary" data-action="generate">✳ 生成建议</button>`)}<div class="settings-note">已保存建议 ${history.length} 组。若模型未配置或调用失败，将自动返回规则统计建议；样本量不足的分组不会被总结为稳定规律。</div><div id="recommendationBox" style="margin-top:15px">${state.recommendation?recommendationView(state.recommendation):history.length?recommendationView(history[0]):emptyState('生成你的第一组排期参考')}</div>`}
function recommendationView(r){const sourceLabel=r.source_label||r.source||'规则分析（未使用大模型）';const items=r.recommendations||[];return `<div class="insight" style="margin-bottom:13px"><span class="insight-symbol">✦</span><div><b>${escapeHtml(sourceLabel)}</b><p>参考 ${r.reference_count??'—'} 条历史内容 · ${r.confidence_note||'建议仅供参考'}${r.fallback_reason?`<br>模型调用失败，已降级：${escapeHtml(r.fallback_reason)}`:''}</p></div></div><div class="grid" style="grid-template-columns:repeat(3,minmax(0,1fr))">${items.map((x,i)=>`<article class="panel suggestion-card"><div class="suggestion-top"><div class="day-badge"><b>${escapeHtml(x.day_of_week)}</b><small>${escapeHtml(x.time_slot)}</small></div><div class="suggestion-copy"><h3 contenteditable="true" data-rec-title="${i}">${escapeHtml(x.title)}</h3><p>${tag(x.content_type)} · ${tag(x.platform,'platform-tag')}</p></div></div><div class="suggestion-meta"><span>参考样本 ${x.reference_sample_count} 条</span><span>${{high:'较充分',medium:'一般',low:'有限'}[x.confidence]||'有限'}</span>${x.prediction_views_low!=null?`<span>预期播放 ${fmt(x.prediction_views_low)}–${fmt(x.prediction_views_high)}</span>`:''}</div><div class="reason-box">${escapeHtml(x.reason)}</div><div class="suggestion-meta"><select data-rec-day="${i}">${WEEKDAYS.map(d=>`<option ${d===x.day_of_week?'selected':''}>${d}</option>`).join('')}</select><input class="time-input" data-rec-time="${i}" type="time" value="${escapeHtml(x.time_slot.length===5?x.time_slot:x.time_slot+':00')}"/><button class="btn-secondary" data-action="edit-suggestion" data-index="${i}">调整</button></div></article>`).join('')}</div><div class="form-actions"><button class="btn-primary" data-action="adopt" data-id="${r.id}">采纳全部建议并加入日历</button></div>`}
async function calendarPage(){const dates=monthDates(),month=dates.find(d=>d.getDate()===1),first=localDate(new Date(month.getFullYear(),month.getMonth(),1)),last=localDate(new Date(month.getFullYear(),month.getMonth()+1,0));state.calendar=await api(`/api/schedule?start=${first}&end=${last}`);const title=`${month.getFullYear()}年 ${pad(month.getMonth()+1)}月`;const monthItems=[...state.calendar].sort((a,b)=>a.planned_date.localeCompare(b.planned_date)||a.planned_time.localeCompare(b.planned_time));return `${heading('PUBLISHING PLAN · 05','排期日历','按月查看计划、负责人和发布状态',`<button class="btn-secondary" data-action="export-calendar">导出 CSV</button>`)}<section class="panel"><div class="panel-head"><div class="calendar-toolbar"><button class="btn-secondary" data-action="week-prev">‹ 上月</button><button class="btn-secondary" data-action="week-next">下月 ›</button><h2 class="week-label">${title}</h2><button class="btn-secondary" data-action="week-today">本月</button><div class="tabs"><button class="tab-btn ${state.calendarMode==='month'?'active':''}" data-mode="month">月历</button><button class="tab-btn ${state.calendarMode==='list'?'active':''}" data-mode="list">月清单</button></div></div></div>${state.calendarMode==='month'?`<div class="calendar-grid month-grid">${['周一','周二','周三','周四','周五','周六','周日'].map(d=>`<div class="month-weekday">${d}</div>`).join('')}${dates.map(d=>{const key=localDate(d),items=d.getMonth()===month.getMonth()?state.calendar.filter(e=>e.planned_date===key):[];return `<div class="calendar-day ${d.getMonth()!==month.getMonth()?'outside-month':''}" data-day="${key}"><div class="calendar-day-head"><b>${d.getDate()}</b></div>${items.map(e=>scheduleEvent(e)).join('')}</div>`}).join('')}</div>`:`<div class="calendar-list">${monthItems.map(e=>`<div class="calendar-list-row"><time>${e.planned_date} ${e.planned_time}</time><b>${escapeHtml(e.title)}</b><span>${escapeHtml(e.category)} · ${escapeHtml(e.platform)} · ${escapeHtml(e.owner||'未分配')} · ${escapeHtml(e.status)} ${['owner','editor'].includes(state.user?.role)?`<button class="btn-secondary" data-action="edit-schedule" data-id="${e.id}">调整</button> ${e.status==='已复盘'?'已回填':`<button class="btn-primary" data-action="publish" data-id="${e.id}">标记发布</button>`}`:''}</span></div>`).join('')||'<p class="hint">本月还没有排期。先生成并采纳一组建议。</p>'}</div>`}<p class="disclaimer" style="margin-top:12px">计划可以调整；回填发布数据后会同步进入内容资产并参与复盘。</p></section>`}
function monthDates(){const now=new Date();const anchor=new Date(now.getFullYear(),now.getMonth()+state.monthOffset,1);const first=new Date(anchor);first.setDate(first.getDate()-((first.getDay()+6)%7));return Array.from({length:42},(_,i)=>{const d=new Date(first);d.setDate(first.getDate()+i);return d})}

function localDate(d){return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
function scheduleEvent(e){const editor=['owner','editor'].includes(state.user?.role);return `<div class="calendar-event ${e.category==='技艺展示'?'alt':''}" ${editor?'draggable="true"':''} data-schedule-id="${e.id}" title="${editor?'拖动到其他日期可改期':'排期记录'}"><b>${escapeHtml(e.title)}</b><small>${e.planned_time} · ${escapeHtml(e.platform)} · ${escapeHtml(e.owner||'未分配')}</small><small class="schedule-state">${escapeHtml(e.status)}</small>${editor?`<div class="event-actions"><button data-action="edit-schedule" data-id="${e.id}">调整</button>${e.status==='已复盘'?'已复盘':`<button data-action="publish" data-id="${e.id}">回填</button>`}</div>`:''}</div>`}
function wirePage(){qsa('.nav-item[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));qsa('[data-goto]').forEach(b=>b.onclick=()=>go(b.dataset.goto));qsa('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b));qsa('[data-mode]').forEach(b=>b.onclick=()=>{state.calendarMode=b.dataset.mode;render()});const csv=qs('#csvFile');if(csv)csv.onchange=e=>e.target.files[0]&&importCsv(e.target.files[0]);qsa('[data-lifecycle]').forEach(el=>el.onchange=()=>updateLifecycle(el.dataset.lifecycle,el.value));wireRecordControls();const ruleForm=qs('#ruleForm');if(ruleForm)ruleForm.onsubmit=saveRule;const form=qs('#aiForm');if(form)form.onsubmit=saveAIConfig;const af=qs('#analysisSettings');if(af)af.onsubmit=saveAnalysisSettings;const hf=qs('#hypothesisForm');if(hf)hf.onsubmit=addHypothesis;const inf=qs('#insightForm');if(inf)inf.onsubmit=generateInsight;const tf=qs('#teamForm');if(tf)tf.onsubmit=createTeam;qsa('[data-provider]').forEach(b=>b.onclick=()=>applyProvider(b.dataset.provider));const teamSel=qs('#teamSelect');if(teamSel)teamSel.onchange=()=>{state.teamId=Number(teamSel.value);localStorage.setItem('artsTeamId',state.teamId);render()};const roleSel=qs('#roleSelect');if(roleSel)roleSel.onchange=()=>{state.role=roleSel.value;localStorage.setItem('artsRole',state.role);render()};loadHypotheses();qsa('[data-rule-toggle]').forEach(b=>b.onclick=()=>toggleRule(b.dataset.ruleToggle));qsa('[data-rule-delete]').forEach(b=>b.onclick=()=>deleteRule(b.dataset.ruleDelete));qsa('[data-rule-run]').forEach(b=>b.onclick=()=>runRules(b.dataset.ruleRun));const uf=qs('#userForm');if(uf)uf.onsubmit=async e=>{e.preventDefault();try{await api('/api/users',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(uf)))});await render();toast('成员账号已创建')}catch(err){toast(err.message)}};qsa('.calendar-day[data-day]').forEach(day=>{day.ondragover=e=>e.preventDefault();day.ondrop=async e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(!id)return;try{await api(`/api/schedule/${id}`,{method:'PATCH',body:JSON.stringify({planned_date:day.dataset.day})});await render();toast('排期已改到 '+day.dataset.day)}catch(err){toast(err.message)}}});qsa('.calendar-event[data-schedule-id]').forEach(ev=>ev.ondragstart=e=>e.dataTransfer.setData('text/plain',ev.dataset.scheduleId))}
async function loadHypotheses(){const el=qs('#hypothesisList');if(!el)return;try{const rows=await api('/api/hypotheses');el.innerHTML=rows.map(x=>`<div class="hypothesis-row"><div><b>${escapeHtml(x.statement)}</b><small>${escapeHtml(x.status)} · ${escapeHtml(x.result||'尚未记录结论')}</small></div><button class="btn-secondary" data-action="hypothesis-status" data-id="${x.id}" data-status="${x.status}">更新状态</button></div>`).join('')||'<p class="hint">记录一个可验证的运营假设。</p>';qsa('[data-action="hypothesis-status"]',el).forEach(b=>b.onclick=async()=>{const status=b.dataset.status==='待验证'?'已验证':'待验证';await api(`/api/hypotheses/${b.dataset.id}`,{method:'PATCH',body:JSON.stringify({status})});loadHypotheses()})}catch(e){el.textContent=e.message}}
async function updateLifecycle(id,lifecycle){try{await api(`/api/contents/${id}`,{method:'PATCH',body:JSON.stringify({lifecycle})});await render();toast('内容状态已更新')}catch(e){toast(e.message)}}
async function importCsv(file){const fd=new FormData();fd.append('file',file);try{const res=await api('/api/contents/import-csv',{method:'POST',body:fd});await render();toast(`导入 ${res.imported} 条`+(res.warnings.length?`，${res.warnings.length} 行需核对`:''));if(res.warnings.length)showInfo('导入提示',res.warnings.map(w=>`第 ${w.row} 行：${w.message}`).join('<br>'))}catch(e){toast(e.message)}}
function openRecordForm(record=null,defaults={}){const x={platform:record?.platform||defaults.platform||'',published_at:record?.published_at||defaults.published_at||defaults.date||new Date().toISOString().slice(0,16),title:record?.title||defaults.title||'',category:record?.category||defaults.category||'演出宣传',duration:record?.duration??'',views:record?.views??'',likes:record?.likes??'',comments:record?.comments??'',saves:record?.saves??'',shares:record?.shares??'',completion:record?.completion??'',tags:(record?.tags||defaults.tags||[]).join?.(',')||record?.tags||defaults.tags||'',lifecycle:record?.lifecycle||'已发布',materials:record?.materials||'',owner:record?.owner||'',notes:record?.notes||'',profile_visits:record?.profile_visits??0,follows:record?.follows??0,attendance:record?.attendance??0,tickets:record?.tickets??0,comment_text:record?.comment_text||''};const label=record?'编辑内容资产':'录入内容资产';showModal(`<div class="modal-head"><div><h2>${label}</h2><p>此记录进入团队私有经验库</p></div><button class="modal-close" data-action="close">×</button></div><form id="recordForm" class="modal-form"><div class="form-grid"><div class="form-field"><label>发布平台</label><input name="platform" required value="${escapeHtml(x.platform)}" placeholder="例如：短视频平台A"/></div><div class="form-field"><label>发布时间</label><input name="published_at" type="datetime-local" required value="${escapeHtml(x.published_at.slice(0,16))}"/></div><div class="form-field full"><label>标题 / 内容方向</label><input name="title" required value="${escapeHtml(x.title)}"/></div><div class="form-field"><label>内容类型</label><select name="category">${CATEGORIES.map(c=>`<option ${c===x.category?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label>状态标签</label><select name="lifecycle">${['已发布','未发布'].map(c=>`<option ${c===x.lifecycle?'selected':''}>${c}</option>`).join('')}</select></div>${[['duration','视频时长（秒）'],['views','播放量'],['likes','点赞量'],['comments','评论量'],['saves','收藏量'],['shares','转发量'],['completion','看完比例（%）']].map(([k,n])=>`<div class="form-field"><label>${n}</label><input name="${k}" type="number" min="0" ${k==='completion'?'max="100"':''} value="${x[k]}"/></div>`).join('')}<div class="form-field"><label>标签（逗号分隔）</label><input name="tags" value="${escapeHtml(x.tags)}"/></div><div class="form-field"><label>责任人</label><input name="owner" value="${escapeHtml(x.owner)}"/></div><div class="form-field full"><label>素材说明</label><input name="materials" value="${escapeHtml(x.materials)}" placeholder="拍摄素材、剪辑文件位置等"/></div><div class="form-field full"><label>备注</label><textarea name="notes" rows="2">${escapeHtml(x.notes)}</textarea></div><div class="form-field"><label>主页访问</label><input name="profile_visits" type="number" min="0" value="${x.profile_visits}"/></div><div class="form-field"><label>新增关注</label><input name="follows" type="number" min="0" value="${x.follows}"/></div><div class="form-field"><label>到场人数</label><input name="attendance" type="number" min="0" value="${x.attendance}"/></div><div class="form-field"><label>售票数</label><input name="tickets" type="number" min="0" value="${x.tickets}"/></div><div class="form-field full"><label>评论摘录（请勿录入个人信息）</label><textarea name="comment_text" rows="2">${escapeHtml(x.comment_text)}</textarea></div></div><div class="form-actions"><button type="button" class="btn-secondary" data-action="close">取消</button><button class="btn-primary">保存资产</button></div></form>`);const form=qs('#recordForm');form.onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(form));for(const k of ['duration','views','likes','comments','saves','shares','completion','profile_visits','follows','attendance','tickets']){data[k]=Number(data[k]||0);if(data[k]<0){toast('数值不能为负数');return}}if(data.completion>100){toast('看完比例不能超过 100%');return}data.tags=data.tags.split(/[,，]/).map(x=>x.trim()).filter(Boolean);try{if(record)await api(`/api/contents/${record.id}`,{method:'PATCH',body:JSON.stringify(data)});else await api('/api/contents',{method:'POST',body:JSON.stringify(data)});closeModal();await render();toast(record?'内容已更新':'内容已入库')}catch(err){toast(err.message)}}}
function closeModal(){qs('#modalRoot').innerHTML=''}function showModal(content){qs('#modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal">${content}</div></div>`;qsa('[data-action="close"]').forEach(b=>b.onclick=closeModal)}function showInfo(title,message){showModal(`<div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close">×</button></div><p>${message}</p><div class="form-actions"><button class="btn-primary" data-action="close">知道了</button></div>`)}
function formAIData(){const data=Object.fromEntries(new FormData(qs('#aiForm')));try{data.platform_weights=data.platform_weights_json?JSON.parse(data.platform_weights_json):(state.settings.platform_weights||{})}catch{toast('平台权重模板不是有效 JSON');return null}delete data.platform_weights_json;data.temperature=Number(data.temperature);data.fallback_enabled=data.fallback_enabled==='true';data.enabled=true;return data}
async function saveAIConfig(e){e.preventDefault();const data=formAIData();if(!data)return;try{state.settings=await api('/api/settings',{method:'PUT',body:JSON.stringify(data)});await render();toast('模型设置已保存在后端')}catch(err){toast(err.message)}}
async function saveAnalysisSettings(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/settings',{method:'PUT',body:JSON.stringify({...state.settings,...d,api_key:''})});await render();toast('分析口径已更新')}catch(err){toast(err.message)}}
function applyProvider(name){const s=SUPPLIERS[name];const form=qs('#aiForm');form.elements.base_url.value=s.url;form.elements.model.value=s.model;form.elements.request_mode.value='base';toast(`已填写 ${name} 接口模板`)}
async function createTeam(e){e.preventDefault();const name=new FormData(e.currentTarget).get('name');try{const t=await api('/api/teams',{method:'POST',body:JSON.stringify({name})});state.teamId=t.id;localStorage.setItem('artsTeamId',t.id);await render();toast('团队已创建并切换')}catch(err){toast(err.message)}}
async function generateInsight(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));const out=qs('#insightResult');out.innerHTML='<p class="hint">正在整理团队记录…</p>';try{const res=await api('/api/ai/insight',{method:'POST',body:JSON.stringify(data)});out.innerHTML=`<div class="insight"><span class="insight-symbol">✦</span><div><b>${escapeHtml(res.source)} · 参考 ${res.sample_count} 条</b><p>${escapeHtml(res.answer)}</p></div></div>`}catch(err){out.textContent=err.message}}
async function addHypothesis(e){e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{await api('/api/hypotheses',{method:'POST',body:JSON.stringify(d)});e.currentTarget.reset();loadHypotheses();toast('假设已记录')}catch(err){toast(err.message)}}
async function action(a,b){try{if(a==='edit-benchmark'){editBenchmark(b);return}if(a==='run-rules'){await runRules(b.dataset.contentId);return}if(a==='retry'){await render();return}if(a==='open-add'){openRecordForm();return}if(a==='edit-record'){const x=state.records.find(c=>c.id===b.dataset.id);openRecordForm(x);return}if(a==='delete-record'){if(confirm('确定删除这条内容记录？')){await api(`/api/contents/${b.dataset.id}`,{method:'DELETE'});state.selectedRecords=state.selectedRecords.filter(id=>id!==b.dataset.id);await render();toast('记录已删除')}return}if(a==='template'){downloadText('艺数智策内容导入模板.csv',contentCsvTemplate(),'text/csv;charset=utf-8');return}if(a==='export-content-csv'){downloadApi('/api/export/contents');return}if(a==='export-report'){downloadApi('/api/report/export');return}if(a==='export-anonymized'){downloadApi('/api/export/anonymized');return}if(a==='handover'){downloadApi('/api/handover/export?format=markdown');return}if(a==='audit'){const rows=await api('/api/audit');showInfo('最近操作记录',rows.slice(0,20).map(x=>`${escapeHtml(x.created_at.slice(0,16))} · ${escapeHtml(x.actor)} · ${escapeHtml(x.action)} · ${escapeHtml(x.detail)}`).join('<br>')||'暂无操作记录');return}if(a==='test-ai'){toast('正在通过后端测试模型连通性…');const r=await api('/api/ai/test',{method:'POST'});toast(`${r.message} · ${r.elapsed_ms}ms`);return}if(a==='save-model-profile'){const data=formAIData();if(!data)return;const saved=await api('/api/ai/configs',{method:'POST',body:JSON.stringify(data)});await api(`/api/ai/configs/${saved.id}/activate`,{method:'POST'});await render();toast('新模型配置已保存并启用');return}if(a==='activate-model'){await api(`/api/ai/configs/${b.dataset.id}/activate`,{method:'POST'});await render();toast('已切换当前模型');return}if(a==='generate'){toast('正在根据团队记录生成建议…');state.recommendation=await api('/api/ai/recommend',{method:'POST'});qs('#recommendationBox').innerHTML=recommendationView(state.recommendation);bindRecommendation();toast(state.recommendation.source_label);return}if(a==='edit-suggestion'){updateRecommendationItem(Number(b.dataset.index));return}if(a==='adopt'){const items=currentEditedRecommendations();const res=await api('/api/schedule/adopt',{method:'POST',body:JSON.stringify({recommendation_id:b.dataset.id,items})});await go('calendar');toast(`已采纳 ${res.created} 条建议并写入日历`);return}if(a==='week-prev'){state.monthOffset--;await render();return}if(a==='week-next'){state.monthOffset++;await render();return}if(a==='week-today'){state.monthOffset=0;await render();return}if(a==='records-prev'){state.recordsPage=Math.max(1,state.recordsPage-1);await renderRecordsOnly();return}if(a==='records-next'){state.recordsPage++;await renderRecordsOnly();return}if(a==='bulk-publish'||a==='bulk-unpublish'){await bulkRecords('set_status',a==='bulk-publish'?'已发布':'未发布');return}if(a==='bulk-delete'){if(confirm(`确定删除已选择的 ${state.selectedRecords.length} 条记录？`))await bulkRecords('delete');return}if(a==='export-calendar'){downloadApi('/api/schedule/export');return}if(a==='edit-schedule'){editSchedule(b.dataset.id);return}if(a==='publish'){publishSchedule(b.dataset.id);return}}catch(e){toast(e.message)}}
function currentEditedRecommendations(){const r=state.recommendation;if(!r)return[];return r.recommendations.map((x,i)=>({...x,title:qs(`[data-rec-title="${i}"]`)?.textContent.trim()||x.title,day_of_week:qs(`[data-rec-day="${i}"]`)?.value||x.day_of_week,time_slot:qs(`[data-rec-time="${i}"]`)?.value||x.time_slot}))}
function bindRecommendation(){qsa('[data-action="edit-suggestion"]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.index);const el=qs(`[data-rec-title="${i}"]`);el.focus();toast('可直接编辑主题，并调整星期和时间')});qsa('#recommendationBox [data-action="adopt"]').forEach(b=>b.onclick=()=>action('adopt',b))}
function downloadText(name,text,mime){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff',text],{type:mime}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function editSchedule(id){const item=state.calendar.find(x=>x.id===id);if(!item)return;showModal(`<h2>调整排期</h2><p>保存后更新服务器日历。</p><form id="scheduleForm"><div class="form-grid"><div class="form-field"><label>计划日期</label><input name="planned_date" type="date" required value="${item.planned_date}"/></div><div class="form-field"><label>发布时间</label><input name="planned_time" type="time" required value="${item.planned_time}"/></div><div class="form-field full"><label>内容主题</label><input name="title" required value="${escapeHtml(item.title)}"/></div><div class="form-field"><label>内容类型</label><select name="category">${CATEGORIES.map(c=>`<option ${c===item.category?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label>发布平台</label><input name="platform" value="${escapeHtml(item.platform)}" required/></div><div class="form-field"><label>负责人</label><input name="owner" value="${escapeHtml(item.owner||'')}"/></div></div><div class="form-actions"><button type="button" class="btn-secondary" data-action="close">取消</button><button class="btn-primary">保存调整</button></div></form>`);qs('#scheduleForm').onsubmit=async e=>{e.preventDefault();try{await api(`/api/schedule/${id}`,{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeModal();await render();toast('日历已更新')}catch(err){toast(err.message)}}}
function publishSchedule(id){const item=state.calendar.find(x=>x.id===id);if(!item)return;showModal(`<h2>回填实际表现</h2><p>实际发布后记录数据，系统会对照预测范围并纳入经验库。</p><form id="publishForm"><div class="form-grid"><div class="form-field full"><label>实际发布标题</label><input name="title" value="${escapeHtml(item.title)}" required/></div><div class="form-field"><label>内容类型</label><select name="category">${CATEGORIES.map(c=>`<option ${c===item.category?'selected':''}>${c}</option>`).join('')}</select></div><div class="form-field"><label>平台</label><input name="platform" value="${escapeHtml(item.platform)}" required/></div><div class="form-field"><label>实际发布时间</label><input name="published_at" type="datetime-local" value="${item.planned_date}T${item.planned_time}" required/></div>${[['views','播放量'],['likes','点赞量'],['comments','评论量'],['saves','收藏量'],['shares','转发量'],['completion','看完比例（%）'],['profile_visits','主页访问'],['follows','新增关注'],['attendance','到场人数'],['tickets','售票数']].map(([k,l])=>`<div class="form-field"><label>${l}</label><input type="number" name="${k}" min="0" ${k==='completion'?'max="100"':''} required value="0"/></div>`).join('')}<div class="form-field full"><label>评论摘录</label><textarea name="comment_text" rows="2"></textarea></div></div><div class="form-actions"><button type="button" class="btn-secondary" data-action="close">取消</button><button class="btn-primary">保存实际数据</button></div></form>`);qs('#publishForm').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));for(const k of ['views','likes','comments','saves','shares','completion','profile_visits','follows','attendance','tickets'])data[k]=Number(data[k]);try{const res=await api(`/api/schedule/${id}/publish`,{method:'POST',body:JSON.stringify(data)});closeModal();await render();const diff=res.prediction.views_deviation_percent;toast(diff==null?'已保存回填数据':`已保存，播放量偏差 ${diff}%`)}catch(err){toast(err.message)}}}
function wireRecordControls(){const search=qs('#recordsSearch');if(search)search.oninput=()=>{state.recordsSearch=search.value;state.recordsPage=1;const pos=search.selectionStart;renderRecordsOnly().then(()=>{const input=qs('#recordsSearch');input?.focus();input?.setSelectionRange(pos,pos)})};for(const [id,key] of [['recordsStatus','recordsStatus'],['recordsPlatform','recordsPlatform'],['recordsCategory','recordsCategory'],['recordsSort','recordsSort'],['recordsOrder','recordsOrder']]){const el=qs('#'+id);if(el)el.onchange=()=>{state[key]=el.value;state.recordsPage=1;renderRecordsOnly()}}const size=qs('#recordsPageSize');if(size)size.onchange=()=>{state.recordsPageSize=Number(size.value);state.recordsPage=1;renderRecordsOnly()};const selectVisible=qs('#selectVisible');if(selectVisible)selectVisible.onchange=()=>{const ids=qsa('[data-record-select]').map(x=>x.dataset.recordSelect);state.selectedRecords=selectVisible.checked?[...new Set([...state.selectedRecords,...ids])]:state.selectedRecords.filter(id=>!ids.includes(id));renderRecordsOnly()};qsa('[data-record-select]').forEach(box=>box.onchange=()=>{state.selectedRecords=box.checked?[...new Set([...state.selectedRecords,box.dataset.recordSelect])]:state.selectedRecords.filter(id=>id!==box.dataset.recordSelect);renderRecordsOnly()})}
async function renderRecordsOnly(){const root=qs('#pageRoot');root.innerHTML=await recordsPage();wirePage()}
async function bulkRecords(action,status){try{await api('/api/contents/bulk',{method:'POST',body:JSON.stringify({ids:state.selectedRecords,action,status})});state.selectedRecords=[];await render();toast(action==='delete'?'已批量删除':'已批量更新状态')}catch(e){toast(e.message)}}
function contentCsvTemplate(){const head=['平台','发布时间','标题','内容类型','时长','播放量','点赞量','评论量','收藏量','转发量','看完比例','状态标签','标签','素材说明','责任人','备注','主页访问','新增关注','到场人数','售票数','评论摘录'];const example=['短视频平台A','2026-10-10 18:30','后台揭秘｜开演前的九十分钟','幕后记录','48','3280','246','38','71','52','68','已发布','后台|准备','排练与候场记录','林老师','首场演出素材','52','6','8','3','节奏清楚'];return [head,example].map(row=>row.map(v=>`"${String(v).replaceAll('"','""')}"`).join(',')).join('\r\n')+'\r\n'}
async function settingsPage(){const s=state.settings,teams=await api('/api/teams'),models=await api('/api/ai/configs'),users=state.user?.role==='owner'?await api('/api/users'):[],rules=await api('/api/rules'),ruleLogs=await api('/api/rules/logs?limit=30');return `${heading('MODEL CONNECTION · 06','模型接口设置','保存后由后端代理调用，API Key 不会发送到浏览器外的目标服务',`<span class="connection-status"><i class="status-dot ${s.configured?'ok':''}"></i>${s.configured?'模型已配置':'当前使用规则统计模式'}</span>`)}<section class="panel"><div class="panel-head"><div><h2 class="panel-title">模型接口</h2><div class="panel-subtitle">配置保存在服务器数据库，所有建议调用共用当前启用配置</div></div></div><div class="settings-note">${s.configured?'模型可用于排期建议和自然语言洞察。':'当前未配置模型，生成建议将使用规则统计模式。'}</div>${models.length>1?`<div class="model-profiles">${models.map(m=>`<div class="model-profile"><span>${escapeHtml(m.name)} · ${escapeHtml(m.model||'未填写')} ${m.enabled?'（当前启用）':''}</span>${m.enabled?'':`<button class="btn-secondary" data-action="activate-model" data-id="${m.id}">设为当前</button>`}</div>`).join('')}</div>`:''}<form id="aiForm" style="margin-top:16px"><div class="provider-row">${Object.keys(SUPPLIERS).map(name=>`<button type="button" class="btn-secondary" data-provider="${name}">${name}</button>`).join('')}</div><div class="form-grid"><div class="form-field full"><label>供应商配置名称</label><input name="name" value="${escapeHtml(s.name||'默认模型')}"/></div><div class="form-field"><label>请求模式</label><select name="request_mode"><option value="base" ${s.request_mode==='base'?'selected':''}>基础地址</option><option value="full" ${s.request_mode==='full'?'selected':''}>完整请求地址</option></select></div><div class="form-field"><label>鉴权方式</label><select name="auth_type"><option value="bearer" ${s.auth_type==='bearer'?'selected':''}>Authorization: Bearer</option><option value="api-key" ${s.auth_type==='api-key'?'selected':''}>api-key</option><option value="custom:X-API-Key" ${s.auth_type==='custom:X-API-Key'?'selected':''}>自定义 X-API-Key</option></select></div><div class="form-field full"><label>Base URL 或完整请求地址</label><input name="base_url" type="url" value="${escapeHtml(s.base_url)}" placeholder="https://api.example.com/v1"/></div><div class="form-field"><label>模型名称</label><input name="model" value="${escapeHtml(s.model)}"/></div><div class="form-field"><label>API Key ${s.has_key?`<small>（已保存 ${escapeHtml(s.key_hint)}；留空保留）</small>`:''}</label><input name="api_key" type="password" autocomplete="new-password" placeholder="${s.has_key?'留空保留原密钥':'填写密钥'}"/></div><div class="form-field"><label>温度</label><input name="temperature" type="number" min="0" max="2" step="0.1" value="${s.temperature}"/></div><div class="form-field"><label>失败自动降级</label><select name="fallback_enabled"><option value="true" ${s.fallback_enabled?'selected':''}>开启规则统计建议</option><option value="false" ${!s.fallback_enabled?'selected':''}>关闭并显示报错</option></select></div><div class="form-field full"><label>平台权重模板（JSON，可留空）</label><textarea name="platform_weights_json" rows="3" placeholder='{"短视频平台A":{"completion":0.68,"interaction":1.15}}'>${escapeHtml(JSON.stringify(s.platform_weights||{},null,2))}</textarea><span class="form-help">示例：{"短视频平台A":{"completion":0.7,"interaction":1.1}}</span></div></div><div class="form-actions"><button class="btn-secondary" type="button" data-action="test-ai">测试连接</button><button class="btn-secondary" type="button" data-action="save-model-profile">另存为新配置</button><button class="btn-primary">保存当前配置</button></div></form></section><section class="panel" style="margin-top:15px"><div class="panel-head"><h2 class="panel-title">分析口径</h2></div><form id="analysisSettings" class="form-grid"><div class="form-field"><label>最小样本门槛</label><input name="min_sample" type="number" min="2" max="1000" value="${s.min_sample}"/></div><div class="form-field"><label>看完比例权重</label><input name="score_completion_weight" type="number" min="0" max="1" step="0.05" value="${s.score_completion_weight}"/></div><div class="form-field"><label>互动表现权重</label><input name="score_interaction_weight" type="number" min="0" max="3" step="0.05" value="${s.score_interaction_weight}"/></div><div class="form-actions"><button class="btn-primary">保存分析口径</button></div></form><p class="disclaimer">低于样本门槛不展示均值；1–2 倍门槛显示“样本较少，仅供参考”。平台口径可能不同。</p></section><section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2 class="panel-title">团队与成员</h2><div class="panel-subtitle">${escapeHtml(teams[0]?.name||'当前团队')} · ${users.length} 位成员</div></div></div>${state.user?.role==='owner'?`<div class="team-members">${users.map(u=>`<div class="hypothesis-row"><div><b>${escapeHtml(u.name)} · ${u.role==='owner'?'负责人':u.role==='editor'?'录入者':'查看者'}</b><small>${escapeHtml(u.email)}</small></div></div>`).join('')}<form id="userForm" class="form-grid" style="margin-top:12px"><div class="form-field"><label>成员姓名</label><input name="name" required/></div><div class="form-field"><label>邮箱</label><input name="email" type="email" required/></div><div class="form-field"><label>初始密码（至少 10 位）</label><input name="password" type="password" minlength="10" required/></div><div class="form-field"><label>角色</label><select name="role"><option value="editor">录入者</option><option value="viewer">查看者</option></select></div><div class="form-actions"><button class="btn-primary">添加成员</button></div></form>`:'<p class="form-help">只有团队负责人可以管理成员。'}<p class="disclaimer">密码使用 PBKDF2 哈希保存；成员权限由服务端会话验证，不依赖浏览器可修改的角色值。</p><button class="btn-secondary" data-action="audit">查看操作记录</button></section><section class="panel" style="margin-top:15px"><div class="panel-head"><div><h2 class="panel-title">内容规则集</h2><div class="panel-subtitle">按优先级从高到低执行；条件为“且”或“或”；保存后立即生效</div></div></div>${['owner','editor'].includes(state.user?.role)?`<form id="ruleForm" class="rule-form"><div class="form-grid"><div class="form-field"><label>规则名称</label><input name="name" required placeholder="高互动内容加复盘标签"/></div><div class="form-field"><label>优先级（数值越大越先执行）</label><input name="priority" type="number" min="0" max="10000" value="100"/></div><div class="form-field"><label>触发时机</label><select name="trigger"><option value="content.create">新增内容</option><option value="content.update">更新内容</option><option value="content.import">CSV 导入</option><option value="manual">手动执行</option></select></div><div class="form-field"><label>条件关系</label><select name="logic"><option value="all">且（全部满足）</option><option value="any">或（任一满足）</option></select></div><div class="form-field full"><label>条件 JSON</label><textarea name="conditions" rows="3">[{"field":"views","operator":"gte","value":1000},{"field":"completion","operator":"gte","value":60}]</textarea><small>字段：platform/category/lifecycle/views/likes/comments/completion/owner/source；运算符：eq、neq、contains、gt、gte、lt、lte。留空数组表示全部命中。</small></div><div class="form-field"><label>生效范围 JSON</label><input name="scope" value='{"platforms":[],"categories":[],"statuses":[]}'/><small>可用 platforms、categories、statuses 数组限制范围。</small></div><div class="form-field"><label>动作 JSON</label><textarea name="actions" rows="3">[{"type":"add_tag","value":"高表现待复盘"}]</textarea><small>动作：set_status、add_tag、set_owner、append_note、set_category。</small></div><label class="rule-enabled"><input name="enabled" type="checkbox" checked/>启用并立即生效</label><div class="form-actions"><button class="btn-primary">保存规则</button><button type="button" class="btn-secondary" data-action="run-rules">手动执行</button></div></div></form>`:'<p class="form-help">当前账号只读，可查看规则配置和执行日志。</p>'}<div class="rule-list">${rules.map(x=>`<div class="rule-row"><div><b>${escapeHtml(x.name)}</b><small>优先级 ${x.priority} · ${escapeHtml(x.trigger)} · ${x.logic==='all'?'且':'或'} · ${(x.conditions||[]).length} 条条件</small></div><span class="status-pill ${x.enabled?'published':'unpublished'}">${x.enabled?'启用':'停用'}</span>${['owner','editor'].includes(state.user?.role)?`<button class="btn-secondary" data-rule-toggle="${x.id}">${x.enabled?'停用':'启用'}</button><button class="btn-secondary" data-rule-delete="${x.id}">删除</button>`:''}</div>`).join('')||'<p class="hint">还没有规则。新建一条规则后会在指定触发时机生效。</p>'}</div><h3 class="panel-title rule-log-title">最近执行日志</h3><div class="rule-logs">${ruleLogs.map(x=>`<div class="rule-log-row"><span>${escapeHtml(x.created_at.slice(0,16).replace('T',' '))}</span><b>${escapeHtml(x.rule_name)}</b><span class="rule-result ${x.result}">${x.result==='matched'?'命中':x.result==='no_match'?'未命中':'错误'}</span><small>${escapeHtml(x.detail)}</small></div>`).join('')||'<p class="hint">规则执行后会在这里记录命中、未命中或错误详情。</p>'}</div></section><section class="panel" style="margin-top:15px"><div class="panel-head"><h2 class="panel-title">数据与隐私</h2><button class="btn-secondary" data-action="export-anonymized">导出脱敏 CSV</button></div><p class="form-help">业务记录存储在 PostgreSQL。可在内网运行；AI 可保持关闭。请勿录入观众个人隐私信息。</p></section>`}
async function saveRule(e){e.preventDefault();const form=e.currentTarget,raw=Object.fromEntries(new FormData(form));try{const body={name:raw.name,priority:Number(raw.priority),trigger:raw.trigger,logic:raw.logic,enabled:form.elements.enabled.checked,conditions:JSON.parse(raw.conditions||'[]'),scope:JSON.parse(raw.scope||'{}'),actions:JSON.parse(raw.actions||'[]')};await api('/api/rules',{method:'POST',body:JSON.stringify(body)});await render();toast('规则已保存并生效')}catch(err){toast(`规则未保存：${err.message}`)}}
async function toggleRule(id){try{const rows=await api('/api/rules'),rule=rows.find(x=>x.id===Number(id));if(!rule)return;await api(`/api/rules/${id}`,{method:'PATCH',body:JSON.stringify({...rule,enabled:!rule.enabled})});await render();toast('规则状态已更新')}catch(e){toast(e.message)}}
async function deleteRule(id){if(!confirm('确定删除这条规则？'))return;try{await api(`/api/rules/${id}`,{method:'DELETE'});await render();toast('规则已删除')}catch(e){toast(e.message)}}
async function runRules(id){const contentId=id||state.records[0]?.id;if(!contentId){toast('没有可用于规则执行的内容记录');return}try{const out=await api('/api/rules/evaluate',{method:'POST',body:JSON.stringify({content_id:contentId})});await render();toast(`手动规则已检查 ${out.checked} 条，命中 ${out.matched} 条`)}catch(e){toast(e.message)}}
function editBenchmark(b){showModal(`<h2>调整团队自身基准</h2><p>${escapeHtml(b.dataset.category)} · 手动基准会标注为团队调整值。</p><form id="benchmarkForm"><input type="hidden" name="category" value="${escapeHtml(b.dataset.category)}"/><div class="form-grid"><div class="form-field"><label>看完比例中位数（%）</label><input name="completion_median" type="number" min="0" max="100" step="0.1" required value="${escapeHtml(b.dataset.value||'0')}"/></div><div class="form-field"><label>互动比例中位数（%）</label><input name="interaction_median" type="number" min="0" step="0.1" required value="${escapeHtml(b.dataset.interaction||'0')}"/></div></div><div class="form-actions"><button type="button" class="btn-secondary" data-action="close">取消</button><button class="btn-primary">保存基准</button></div></form>`);qs('#benchmarkForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));d.completion_median=Number(d.completion_median);d.interaction_median=Number(d.interaction_median);try{await api('/api/benchmark',{method:'PUT',body:JSON.stringify(d)});closeModal();await render();toast('自身基准已更新')}catch(err){toast(err.message)}}}
function authPage(setup=false){const isSetup=setup===true,isRegister=setup==='register-team',needsFields=isSetup||isRegister;document.body.classList.add('auth-mode');qs('#sidebar').classList.add('auth-hidden');qs('#crumb').textContent=needsFields?'创建团队':'账号登录';qs('#pageRoot').innerHTML=`<div class="auth-shell"><div class="eyebrow">ARTSMART STRATEGY</div><h1>${needsFields?'创建团队管理员':'登录艺数智策'}</h1><p>${needsFields?'设置团队与负责人账号，建立独立的私有数据空间。':'使用团队负责人提供的邮箱与密码登录。'}</p><form id="authForm" class="auth-form">${needsFields?`<label>团队名称<input name="team_name" required value="示例艺术团队"/></label><label>你的姓名<input name="name" required/></label>`:''}<label>邮箱<input name="email" type="email" required autocomplete="username"/></label><label>密码<input name="password" type="password" required minlength="10" autocomplete="${needsFields?'new-password':'current-password'}"/></label><div id="authError" class="auth-error"></div><button class="btn-primary">${needsFields?'创建账号并进入':'登录'}</button></form>${needsFields?'':'<button id="createTeamAccount" class="btn-secondary" style="margin-top:10px">创建新的团队空间</button>'}<p class="disclaimer">你的记录仅在当前团队空间内可见。建议部署在本机或团队内网。</p></div>`;qs('#authForm').onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.currentTarget));try{const path=isSetup?'/api/auth/setup':isRegister?'/api/auth/register-team':'/api/auth/login';const res=await api(path,{method:'POST',body:JSON.stringify(d)});sessionStorage.setItem('artsSessionToken',res.access_token);state.user=res.user;state.teamId=res.user.team_id;localStorage.setItem('artsTeamId',state.teamId);document.body.classList.remove('auth-mode');qs('#sidebar').classList.remove('auth-hidden');await render();setIdentity();toast('登录成功')}catch(err){const message=qs('#authError');if(message)message.textContent=err.message;else toast(err.message)}};const create=qs('#createTeamAccount');if(create)create.onclick=()=>authPage('register-team')}
function setIdentity(){if(!state.user)return;qs('#teamName').textContent=state.user.team_name;qs('#userName').textContent=state.user.name;qs('#userRole').textContent=state.user.role==='owner'?'团队负责人':state.user.role==='editor'?'内容录入者':'只读查看者'}
async function init(){qs('#todayLabel').textContent=new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'short'}).format(new Date());qs('#menuToggle').onclick=()=>qs('#sidebar').classList.toggle('open');qs('#resetData').onclick=async()=>{try{await api('/api/auth/logout',{method:'POST'})}catch{}sessionStorage.removeItem('artsSessionToken');state.user=null;authPage(false)};try{const status=await api('/api/auth/status');if(status.setup_required){authPage(true);return}const token=sessionStorage.getItem('artsSessionToken');if(!token){authPage(false);return}state.user=await api('/api/auth/me');state.teamId=state.user.team_id;localStorage.setItem('artsTeamId',state.teamId);setIdentity();qs('#sidebar').classList.remove('auth-hidden');await render()}catch(e){authPage(false)}}
init();
